'use strict';
const majorData=[
['Шут','Новый путь','Ты стоишь у начала нового пути. Любопытство полезнее попыток всё предусмотреть.','Сделай небольшой шаг, но сначала проверь, куда ставишь ногу.'],
['Маг','Возможности','Нужные инструменты уже у тебя. Самое время превратить идею в конкретное действие.','Выбери один навык и примени его сегодня.'],
['Верховная Жрица','Интуиция','Не все ответы лежат на поверхности. Пауза поможет услышать собственные мысли.','Не торопись с выводами: понаблюдай и собери информацию.'],
['Императрица','Забота и рост','То, чему ты уделяешь внимание, постепенно расцветает. Оставь место удовольствию и заботе.','Поддержи то, что хочешь вырастить: отношения, идею или себя.'],
['Император','Опора','Ясные границы и понятный план помогут почувствовать почву под ногами.','Определи, что зависит от тебя, и наведи там порядок.'],
['Иерофант','Опыт и традиции','Чужой опыт может пригодиться, если не превращать его в единственно верный путь.','Поговори с человеком, чьему опыту доверяешь.'],
['Влюблённые','Выбор сердцем','Важен выбор, который согласуется с твоими ценностями. Близость начинается с честности.','Спроси себя, чего ты хочешь на самом деле.'],
['Колесница','Движение','Разные желания тянут в разные стороны. Выбранное направление поможет двигаться уверенно.','Сформулируй цель и ближайший посильный шаг.'],
['Справедливость','Честность','Посмотри на ситуацию без удобных оправданий. Решения имеют последствия для всех участников.','Проверь факты и договорённости перед решением.'],
['Отшельник','Внутренний свет','Тишина помогает отделить собственные желания от чужих ожиданий.','Выдели время без уведомлений и чужих советов.'],
['Колесо Фортуны','Перемены','Обстоятельства меняются. Не всё можно контролировать, зато можно выбрать свою реакцию.','Подумай, к чему стоит приспособиться, а что можно отпустить.'],
['Сила','Мягкая смелость','Терпение и доброта бывают убедительнее давления. Смелость не обязана быть громкой.','Отнесись бережно к себе и спокойно обозначь границы.'],
['Повешенный','Другой взгляд','Пауза не равна поражению. С другой точки зрения привычная задача может выглядеть иначе.','Отложи привычный способ решения и попробуй другой.'],
['Безымянный аркан','Завершение','Один этап подходит к концу и освобождает место следующему. Это символ перемен, а не буквальной смерти.','Назови то, что уже отжило, и разреши себе двигаться дальше.'],
['Умеренность','Равновесие','Постепенный ритм помогает соединить то, что кажется несовместимым.','Выбери устойчивый темп вместо очередного рывка.'],
['Дьявол','Привязанности','Привычный комфорт иногда становится ловушкой. Полезно заметить, что отнимает свободу выбора.','Проверь, чего ты хочешь, а что делаешь по привычке.'],
['Башня','Освобождение','Неустойчивые конструкции требуют пересмотра. Эта карта предлагает проверить опоры, а не ждать беды.','Найди слабое место плана и подготовь запасной вариант.'],
['Звезда','Надежда','После напряжения можно возвращать доверие к себе маленькими шагами.','Сделай что-то простое, что возвращает ощущение сил.'],
['Луна','Неопределённость','Воображение заполняет пробелы, когда мало фактов. Не каждая тревожная мысль описывает реальность.','Отдели известное от предположений и задай уточняющий вопрос.'],
['Солнце','Радость и ясность','Есть повод заметить хорошее и позволить себе радость без дополнительных условий.','Поделись тёплым моментом с близким человеком.'],
['Суд','Пробуждение','Можно по-новому оценить пройденный путь и перестать жить по старому сценарию.','Заметь, чему научил опыт, и выбери следующий шаг.'],
['Мир','Целостность','Части истории складываются вместе. Полезно признать сделанное, прежде чем начинать новое.','Отметь завершённое и поблагодари себя за путь.']];
const suits=[{id:'wands',name:'Жезлы',color:'#b56848',topic:'инициативы, творчества и энергии',symbol:'жезл',base:'Твоя энергия ищет выход. Важно выбрать дело, которое действительно тебя увлекает.'},{id:'cups',name:'Кубки',color:'#619fba',topic:'чувств, близости и отношений',symbol:'кубок',base:'Эмоции помогают понять свои потребности. Дай им место, сохраняя уважение к границам других.'},{id:'swords',name:'Мечи',color:'#9aa7c2',topic:'мыслей, решений и честного разговора',symbol:'меч',base:'Ясность начинается с точных вопросов. Проверь, где факты, а где догадки.'},{id:'pentacles',name:'Пентакли',color:'#ad9c54',topic:'работы, ресурсов и повседневных дел',symbol:'пентакль',base:'Небольшие практические действия создают опору. Обрати внимание на доступные ресурсы.'}];
const ranks=['Туз','Двойка','Тройка','Четвёрка','Пятёрка','Шестёрка','Семёрка','Восьмёрка','Девятка','Десятка','Паж','Рыцарь','Королева','Король'];
const genitive={wands:'Жезлов',cups:'Кубков',swords:'Мечей',pentacles:'Пентаклей'};
const stages=['Появляется возможность начать.','Нужно сопоставить два пути.','Сотрудничество помогает идее развиваться.','Стоит укрепить основу и дать себе передышку.','Разногласия показывают, что нуждается во внимании.','Обмен поддержкой восстанавливает равновесие.','Пора проверить выбранное направление.','Практика и последовательность приносят ясность.','Заметь пройденный путь и сохрани свои границы.','Этап достигает полноты; проверь, не берёшь ли ты слишком много.','Любопытство и готовность учиться открывают возможности.','Желание действовать велико: соотнеси скорость с направлением.','Бережное и зрелое отношение помогает поддержать себя и других.','Ответственность означает разумно распоряжаться влиянием.'];
const tips=['Начни с одного небольшого действия.','Сравни варианты с учётом своих ценностей.','Попроси о помощи или предложи сотрудничество.','Позаботься о том, что уже работает.','Обсуди разногласия без обвинений.','Прими поддержку и подумай, чем можешь ответить.','Проверь ожидания и скорректируй план.','Посвяти время практике без спешки.','Признай свой прогресс и не забывай об отдыхе.','Заверши одно дело, прежде чем брать следующее.','Задай вопрос и попробуй новое.','Перед рывком проверь цель.','Будь внимательнее к своим потребностям.','Выбери решение, которое выдержит проверку временем.'];
const numerals=['0','I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX','XXI'];
const deck=majorData.map((m,i)=>({id:i,name:m[0],keyword:m[1],meaning:m[2],tip:m[3],family:'major',number:i,mark:numerals[i]}));
suits.forEach(s=>ranks.forEach((r,i)=>deck.push({id:deck.length,name:r+' '+genitive[s.id],keyword:s.name+' · '+(i<10?String(i+1):r),meaning:stages[i]+' В области '+s.topic+' '+s.base[0].toLowerCase()+s.base.slice(1),tip:tips[i],family:s.id,number:i+1,mark:i<10?String(i+1):['П','Р','К','К'][i-10]})));
const $=id=>document.getElementById(id);
const escapeXML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function star(x,y,r=9){return `<path d="M${x} ${y-r}l${r*.3} ${r*.7} ${r*.7} ${r*.3}-${r*.7} ${r*.3}-${r*.3} ${r*.7}-${r*.3}-${r*.7}-${r*.7}-${r*.3} ${r*.7}-${r*.3}Z" fill="#ead4a0"/>`;}
function banana(x,y,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})"><path d="M-15-8Q-14 27 19 10Q-1 18-6-9Z" fill="#f9d44f" stroke="#b18535" stroke-width="1.5"/><path d="M-15-8l1-6 7 2 1 4" fill="#6b6540"/></g>`;}
function person(x,y,scale=1,eyes=2,pose=0,crown=false){return `<g transform="translate(${x} ${y}) scale(${scale})"><ellipse cy="65" rx="29" ry="7" fill="#0003"/><rect x="-27" y="-50" width="54" height="110" rx="26" fill="url(#body)" stroke="#b88b36" stroke-width="1.6"/><path d="M-27 19L-13 23V12H13V23L27 19V40Q27 60 9 60H-9Q-27 60-27 40Z" fill="#416b99" stroke="#254464" stroke-width="1.5"/><path d="M-23 8L-14 23M23 8L14 23" stroke="#416b99" stroke-width="6"/><rect x="-9" y="28" width="18" height="13" rx="3" fill="#2a5279"/><path d="M-17 58v8h-12M17 58v8h12" fill="none" stroke="#29323d" stroke-width="9" stroke-linecap="round"/><path d="M-24 13Q-38 ${pose?'-8':'25'}-37 36M24 13Q38 ${pose?'-15':'25'} 37 36" fill="none" stroke="#e7bd3f" stroke-opacity="1" stroke-width="9" stroke-linecap="round"/><circle cx="-37" cy="36" r="6" fill="#303640"/><circle cx="37" cy="36" r="6" fill="#303640"/><path d="M-28-21H28" stroke="#303640" stroke-width="8"/>${(eyes===2?[-12,12]:[0]).map(cx=>`<circle cx="${cx}" cy="-21" r="${eyes===2?14:19}" fill="#c5cbd0" stroke="#687780" stroke-width="3"/><circle cx="${cx}" cy="-21" r="${eyes===2?10:14}" fill="#fffdf2"/><circle cx="${cx+2}" cy="-20" r="5" fill="#72513a"/><circle cx="${cx+2}" cy="-20" r="2.5" fill="#20232b"/><circle cx="${cx+4}" cy="-23" r="1.8" fill="white"/>`).join('')}<path d="M-9 0Q0 9 10 0" fill="none" stroke="#795431" stroke-width="2.4" stroke-linecap="round"/>${crown?'<path d="M-23-48l-3-20 15 9 11-17 11 17 15-9-3 20Z" fill="#d9b460" stroke="#f1d899" stroke-width="2"/>':'<path d="M-6-49l-4-10M0-50v-12M6-49l4-10" stroke="#303640" stroke-width="2"/>'}</g>`;}
function suitIcon(type,x,y,size=1){let shape={wands:'<path d="M0 19V-18M0-8Q-15-18-9-4M0 3Q15-9 10 5" fill="none" stroke="#b98b59" stroke-width="5" stroke-linecap="round"/><ellipse cx="-9" cy="-8" rx="4" ry="7" fill="#8eaa78"/>',cups:'<path d="M-13-14H13L10 0Q0 15-10 0Z" fill="#dcc18b" stroke="#fff0b3" stroke-width="1.5"/><path d="M0 6v13M-9 19H9" stroke="#dcc18b" stroke-width="3"/>',swords:'<path d="M0-24L5 5H-5Z" fill="#dfe5e5" stroke="#8fa8b3"/><path d="M-10 7H10M0 7v13" stroke="#c7ac6a" stroke-width="4"/>',pentacles:'<circle r="16" fill="#b4934a" stroke="#edd399" stroke-width="2"/><path d="M0-11L6 9-10-3H10L-6 9Z" fill="none" stroke="#f8e6af" stroke-width="1.5"/>'}[type];return `<g transform="translate(${x} ${y}) scale(${size})">${shape}</g>`;}
function majorScene(i){const p=(x=100,y=155,s=1,e=2,pose=0,c=false)=>person(x,y,s,e,pose,c);switch(i){case 0:return `<path d="M15 217L122 208 139 245H15Z" fill="#455264"/><path d="M94 117L151 83" stroke="#b89260" stroke-width="4"/><path d="M141 85q30-8 20 20t-28-12" fill="#a26e65"/>${p(88,151,.88,2,1)}${banana(148,102,.5)}`;case 1:return `${p(100,139,.85,1,1)}<path d="M38 201H163M48 201v35M152 201v35" stroke="#b89761" stroke-width="7"/>${suitIcon('cups',68,187,.55)}${suitIcon('swords',115,184,.5)}${banana(143,190,.4)}`;case 2:return `<path d="M29 69V231M170 69V231" stroke="#758699" stroke-width="17"/>${p(100,159,.9,2)}<path d="M70 172L100 180 130 172V195L100 201 70 195Z" fill="#eee0b8"/>${star(100,70,14)}`;case 3:return `<path d="M46 132h109v95H46Z" fill="#8e7764"/>${p(100,153,.9,2,0,true)}${[35,161].map(x=>`<path d="M${x} 232v-51" stroke="#83a079" stroke-width="3"/>${star(x,179,9)}`).join('')}`;case 4:return `<path d="M49 96H151V236H49Z" fill="#6c6665" stroke="#b9a17b" stroke-width="4"/>${p(100,163,.93,1,0,true)}${suitIcon('wands',151,158,.8)}`;case 5:return `${p(100,130,.85,2,0,true)}${p(54,206,.4,1)}${p(145,206,.4,2)}<path d="M151 86v107M140 100h22M143 115h16" stroke="#d1b878" stroke-width="4"/>`;case 6:return `${p(64,173,.72,2)}${p(139,173,.72,1)}<path d="M100 113C60 87 83 67 100 85C120 65 139 89 100 113" fill="#c37d7b"/>${star(100,61,10)}`;case 7:return `${p(100,133,.8,1,1,true)}<path d="M40 182H159L147 222H52Z" fill="#596d87" stroke="#d3bd85" stroke-width="2"/><circle cx="58" cy="225" r="17" fill="#283247" stroke="#cbb281" stroke-width="4"/><circle cx="141" cy="225" r="17" fill="#283247" stroke="#cbb281" stroke-width="4"/>`;case 8:return `${p(100,162,.9,2,0,true)}<path d="M48 100v73M25 119h47M29 120l-10 30h22ZM64 120l-10 30h22Z" fill="none" stroke="#dcc48c" stroke-width="2"/>${suitIcon('swords',155,149,1.1)}`;case 9:return `<path d="M68 129Q100 58 132 129V228H68Z" fill="#778285"/>${p(100,167,.78,1)}<path d="M151 120v112" stroke="#c5b17b" stroke-width="4"/><rect x="36" y="111" width="22" height="32" rx="3" fill="#f7da88"/>${star(47,127,8)}`;case 10:return `<circle cx="100" cy="154" r="57" fill="#28374d" stroke="#c5aa73" stroke-width="6"/>${[0,60,120,180,240,300].map(a=>`<path d="M100 154L${100+54*Math.cos(a*Math.PI/180)} ${154+54*Math.sin(a*Math.PI/180)}" stroke="#c5aa73" stroke-width="3"/>`).join('')}${p(100,110,.42,1,1)}${banana(63,176,.7)}${banana(141,178,.7)}`;case 11:return `${p(78,158,.9,2)}<ellipse cx="142" cy="201" rx="32" ry="25" fill="#ba8d55"/><circle cx="135" cy="172" r="29" fill="#a77a49"/><circle cx="135" cy="174" r="20" fill="#e9bf70"/><circle cx="128" cy="169" r="2"/><circle cx="143" cy="169" r="2"/>${banana(128,190,.5)}`;case 12:return `<path d="M37 75H162M46 75v164M154 75v164M100 75v40" stroke="#92806a" stroke-width="7"/><g transform="rotate(180 100 169)">${p(100,169,.8,1)}</g>`;case 13:return `<path d="M29 215Q99 179 174 217V248H29Z" fill="#617d69"/>${p(82,154,.8,1)}<path d="M143 92V230M143 93Q173 84 181 123" fill="none" stroke="#d0c8af" stroke-width="4"/><path d="M142 229v-20m0 7q-18-15-21-1m21-2q19-15 21-1" stroke="#b4bd81" fill="none" stroke-width="3"/>`;case 14:return `<path d="M61 120Q6 86 36 171L72 187M139 120Q194 86 164 171L128 187" fill="#bec7b4"/>${p(100,158,.9,2,1)}${suitIcon('cups',54,157,.7)}${suitIcon('cups',149,183,.7)}<path d="M58 160Q89 169 144 182" stroke="#8ab5c3" stroke-width="3" fill="none"/>`;case 15:return `${p(100,139,1,1)}<path d="M77 91L65 62 92 83M109 83l27-21-13 30" fill="#ba7666"/>${p(48,210,.36,1)}${p(151,210,.36,2)}<path d="M48 193Q100 226 151 193" stroke="#c1b79b" fill="none" stroke-dasharray="4 3"/>${banana(100,231,.7)}`;case 16:return `<path d="M75 227L81 108H127L134 227Z" fill="#80898d" stroke="#c4ba9e" stroke-width="2"/><path d="M125 52L101 104H124L93 145 145 86H121Z" fill="#f4d283"/><path d="M83 98L72 78 103 82 116 71 133 92" fill="#d8b572"/>${person(45,174,.5,1,1)}<g transform="rotate(25 160 188)">${p(160,188,.45,2,1)}</g>`;case 17:return `${star(100,83,27)}${star(49,101,9)}${star(151,102,9)}<path d="M20 221Q61 204 101 222T180 220" fill="none" stroke="#7da5b0" stroke-width="8"/>${p(100,165,.78,2)}${suitIcon('cups',56,200,.7)}${suitIcon('cups',148,200,.7)}`;case 18:return `<circle cx="104" cy="90" r="29" fill="#e2d3a4"/><circle cx="116" cy="81" r="24" fill="#283b53"/><path d="M27 207V133h23v74M149 207v-74h23v74" fill="#657080"/><path d="M93 240q-30-35 10-51t-4-40" fill="none" stroke="#a7a581" stroke-width="12"/>${p(58,200,.45,1)}${p(144,201,.45,2)}`;case 19:return `<circle cx="100" cy="91" r="28" fill="#e8c76f"/>${Array.from({length:12},(_,n)=>{let a=n*Math.PI/6;return `<path d="M${100+34*Math.cos(a)} ${91+34*Math.sin(a)}l${12*Math.cos(a)} ${12*Math.sin(a)}" stroke="#e8c76f" stroke-width="3"/>`}).join('')}${p(63,187,.65,2,1)}${p(139,187,.65,1,1)}`;case 20:return `<path d="M80 89L154 64V99L80 100Z" fill="#d9bb78"/>${p(65,98,.48,1,1)}${[52,100,148].map((x,n)=>p(x,204,.46,n%2+1,1)).join('')}<path d="M35 165L52 147 69 165" stroke="#d9bb78" fill="none" stroke-width="2"/>`;default:return `<ellipse cx="100" cy="155" rx="58" ry="83" fill="none" stroke="#9eae7b" stroke-width="11" stroke-dasharray="5 3"/>${p(100,162,.85,2,1)}${[ [30,70],[169,70],[30,238],[169,238]].map(([x,y],n)=>star(x,y,11)).join('')}`;}}
let svgSerial=0;
function cardSVG(card){const uid="art"+(svgSerial++);let i=card.id,major=card.family==='major',suit=suits.find(s=>s.id===card.family),accent=major?'#b9a578':suit.color;let art;if(major)art=majorScene(card.number);else {let n=card.number,count=n<=10?n:1;let icons=Array.from({length:count},(_,j)=>{let cols=count===1?1:count<5?2:3;let rows=Math.ceil(count/cols);let x=cols===1?100:45+(j%cols)*110/(cols-1);let y=rows===1?90:66+Math.floor(j/cols)*83/Math.max(1,rows-1);return suitIcon(card.family,x,y,count>7?.48:.62)}).join('');art=icons+person(100,n<=10?194:177,n<=10?.63:.94,n%2+1,n===12?1:0,n>=13);if(n===12)art+=`<path d="M37 238Q49 196 76 225L158 220 170 239Z" fill="#84949e"/>`;if(n>=13)art=`<path d="M48 124H152V237H48Z" fill="${accent}" opacity=".4"/>`+art;if(n===11)art+=`<path d="M81 119Q100 79 120 119Z" fill="${accent}"/>`;}
return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 326" role="img" aria-label="${escapeXML(card.name)}"><defs><linearGradient id="body"><stop stop-color="#ffe586"/><stop offset=".5" stop-color="#f1cc52"/><stop offset="1" stop-color="#dca936"/></linearGradient><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#253b56"/><stop offset="1" stop-color="${accent}" stop-opacity=".65"/></linearGradient></defs><rect x="1" y="1" width="198" height="324" rx="11" fill="#e4d5b4" stroke="#d7bd83" stroke-width="2"/><rect x="8" y="8" width="184" height="310" rx="7" fill="#14273b" stroke="#a88e5b"/><path d="M15 47H185V260H15Z" fill="url(#sky)"/>${[[32,62],[162,82],[55,98],[143,59]].map(([x,y],n)=>star(x,y,2+n%2)).join('')}<path d="M15 243Q62 226 101 242T185 240V260H15Z" fill="#344854"/><g>${art}</g><path d="M15 47H185V260H15Z" fill="none" stroke="#b59c6c"/><text x="100" y="33" text-anchor="middle" fill="#e5d4a9" font-size="15" font-family="Georgia">${card.mark}</text><text x="100" y="285" text-anchor="middle" fill="#e9dcb8" font-family="Georgia" font-size="${card.name.length>19?10:12}">${escapeXML(card.name.toUpperCase())}</text><text x="100" y="306" text-anchor="middle" fill="#aeaa97" font-size="7" letter-spacing="1.5">БАНАНОВЫЙ ОРАКУЛ</text>${star(24,28,4)}${star(176,28,4)}</svg>`.replace(/id="(body|sky)"/g,(_,id)=>`id="${uid}-${id}"`).replace(/url\(#(body|sky)\)/g,(_,id)=>`url(#${uid}-${id})`);}
const waiteByName=new Map(WAITE_READINGS.map(r=>[r.name,r]));
for(const c of deck){const r=waiteByName.get(c.name);if(!r)throw Error('Missing reading: '+c.name);c.reading=r;c.keyword=r.theme;c.meaning=r.upright;}
// Waite–Smith numbering; stable internal IDs preserve existing scene mappings.
deck[8].mark='XI';deck[11].mark='VIII';
let positions=['Карта 1'];
let spreadType='free';
const spreadTypes={free:[],day:['Совет дня'],timeline:['Прошлое','Настоящее','Будущее'],choice:['Первый путь','Второй путь','На что обратить внимание'],relationship:['Ты','Другой человек','Что между вами'],cross:['Ситуация','Препятствие','Опора','Следующий шаг','Возможный итог']};
function limit(){return spreadType==='free'?($('major-only').checked?22:78):positions.length;}
let selected=[],revealed=new Set(),busy=false,generation=0;
let pile=[],method='overhand',shuffleCount=0,readingQuestion='',allowReversed=false;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const wait=ms=>new Promise(r=>setTimeout(r,reducedMotion?0:ms));
function back(){return '<div class="card-back"><div class="back-inner"><div class="sigil"></div></div></div>';}
function randomIndex(max){const bound=Math.floor(4294967296/max)*max;let v;do{v=crypto.getRandomValues(new Uint32Array(1))[0]}while(v>=bound);return v%max;}
function freshPile(){const list=deck.filter(card=>!$("major-only").checked||card.family==='major').map(card=>({card,reversed:false}));for(let i=list.length-1;i>0;i--){const j=randomIndex(i+1);[list[i],list[j]]=[list[j],list[i]];}return list;}
// All operations preserve the same cards; the final array element is the top card.
function shufflePile(list,kind){let cards=[...list];if(kind==='overhand'){let next=[];while(cards.length){const n=Math.min(cards.length,2+randomIndex(9));next.push(...cards.splice(-n));}cards=next;}else if(kind==='riffle'){const split=Math.floor(cards.length/2)+randomIndex(7)-3;let left=cards.slice(0,split),right=cards.slice(split),next=[];while(left.length||right.length){const source=!left.length?right:!right.length?left:randomIndex(left.length+right.length)<left.length?left:right;next.push(source.shift());}cards=next;}else{for(let i=cards.length-1;i>0;i--){const j=randomIndex(i+1);[cards[i],cards[j]]=[cards[j],cards[i]];}}return cards;}
let audioContext;
function rustle(strength=1){if(!$('sound').checked)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const buffer=audioContext.createBuffer(1,Math.floor(audioContext.sampleRate*.12),audioContext.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.pow(1-i/data.length,3);const source=audioContext.createBufferSource(),filter=audioContext.createBiquadFilter(),gain=audioContext.createGain();source.buffer=buffer;filter.type='highpass';filter.frequency.value=1700;gain.gain.value=.08*strength;source.connect(filter);filter.connect(gain);gain.connect(audioContext.destination);source.start();}catch{}}
function progress(step){$('ritual-progress').querySelectorAll('span').forEach((el,i)=>{el.classList.toggle('current',i===step);el.classList.toggle('done',i<step)})}
function controls(){const started=selected.length>0;for(const id of ['shuffle','cut'])$(id).disabled=busy||started;$('draw').disabled=busy||selected.length>=limit();$('deck-hit').disabled=busy||selected.length>=limit();$('reversed').disabled=busy||started;$('major-only').disabled=busy||started;$('spread-type').disabled=busy||started;$('undo').disabled=busy||!started;$('restart-table').disabled=busy;$('export').disabled=busy||revealed.size===0;$('ask-chatgpt').disabled=busy||revealed.size===0;document.querySelectorAll('[data-method]').forEach(b=>b.disabled=busy||started);$('deck-count').textContent=String(pile.length);$('draw').textContent=selected.length>=limit()?'Все карты на столе ':'Взять верхнюю карту ';}
function drawStack(){const root=$('deck-stack');root.innerHTML=pile.map((_,i)=>`<div class="physical-card" style="transform:translate3d(0,0,${i*.38}px)" data-layer="${i}">${back()}</div>`).join('');$('deck-hit').style.transform=`translateZ(${pile.length*.38+3}px)`;controls();}
function reset(){generation++;busy=false;selected=[];revealed.clear();pile=freshPile();shuffleCount=0;readingQuestion='';positions=spreadType==='free'?['Карта 1']:[...spreadTypes[spreadType]];$('table-scene').classList.remove('camera-close');$('results').hidden=true;$('status').textContent='Выбери способ перемешивания. Затем нажми на колоду или потяни верхнюю карту вниз.';$('spread').innerHTML=positions.map((p,i)=>`<div class="slot empty-slot"><span>${p.toUpperCase()}</span><button class="card-button table-slot" data-slot="${i}" aria-label="${p}: место для карты" disabled><div class="slot-placeholder"><span>0${i+1}</span><small>Карта ждёт в колоде</small></div></button><small>${spreadType==='free'?'Тяни в своём ритме':'Нажми после вытягивания'}</small></div>`).join('');progress(0);drawStack();}
function getLayers(){return [...$('deck-stack').children];}
async function animateLayers(kind){const layers=getLayers(),n=layers.length;const width=$('deck-anchor').offsetWidth;const duration=kind==='wash'?1800:1400;let animations=[];layers.forEach((el,i)=>{const z=i*.38,base=`translate3d(0,0,${z}px)`;let frames;if(kind==='riffle'){const side=i<n/2?-1:1;frames=[{transform:base,offset:0},{transform:`translate3d(${side*width*.73}px,0,${z+22}px) rotateY(${side*-12}deg) rotateZ(${side*9}deg)`,offset:.32},{transform:`translate3d(${side*width*.18}px,${i%2?7:-7}px,${z+15}px) rotateZ(${side*3}deg)`,offset:.72},{transform:base,offset:1}];}else if(kind==='overhand'){const group=Math.floor(i/13),side=group%2?1:-1;frames=[{transform:base,offset:0},{transform:`translate3d(${side*width*.55}px,${-30-group*8}px,${z+55}px) rotateZ(${side*9}deg)`,offset:.25},{transform:`translate3d(${side*width*.3}px,${group*6}px,${(n-i)*.38+20}px) rotateZ(${side*-4}deg)`,offset:.65},{transform:base,offset:1}];}else{const a=i*2.39996,r=width*(.35+(i%11)/12);const x=Math.cos(a)*r,y=Math.sin(a)*r*.67;frames=[{transform:base,offset:0},{transform:`translate3d(${x}px,${y}px,${i*.05}px) rotateZ(${i*37%360}deg)`,offset:.28},{transform:`translate3d(${-x*.8}px,${-y*.9}px,${i*.05+5}px) rotateZ(${i*47%360+120}deg)`,offset:.64},{transform:base,offset:1}];}if(!reducedMotion)animations.push(el.animate(frames,{duration,delay:kind==='overhand'?(i%13)*12:i%7*12,easing:'cubic-bezier(.45,0,.2,1)'}).finished);});rustle();await wait(350);rustle(.7);await wait(350);rustle(.9);await Promise.all(animations);}
async function shuffle(){if(busy||selected.length)return;busy=true;controls();const token=generation;$('status').textContent=({overhand:'Снимаем небольшие пакеты и перекладываем из руки в руку…',riffle:'Делим колоду надвое и переплетаем карты…',wash:'Рассыпаем карты на столе. Пусть немного пошалят…'})[method];await animateLayers(method);if(token!==generation)return;pile=shufflePile(pile,method);shuffleCount++;busy=false;drawStack();progress(1);$('status').textContent=`Колода перемешана: ${shuffleCount}. Можно повторить, снять колоду или взять верхнюю карту.`;}
async function cutDeck(){if(busy||selected.length)return;busy=true;controls();const token=generation;const split=1+randomIndex(pile.length-1);$('status').textContent='Снимаем верхнюю часть колоды и кладём её под низ…';const layers=getLayers();const width=$('deck-anchor').offsetWidth;const animations=layers.map((el,i)=>{const upper=i>=split,z=i*.38;return reducedMotion?Promise.resolve():el.animate([{transform:`translate3d(0,0,${z}px)`},{transform:`translate3d(${upper?width*.9:-width*.1}px,${upper?-12:0}px,${z+(upper?40:0)}px)`,offset:.4},{transform:`translate3d(${upper?width*.9:0}px,0,${(upper?i-split:i+pile.length-split)*.38}px)`,offset:.7},{transform:`translate3d(0,0,${(upper?i-split:i+pile.length-split)*.38}px)`}],{duration:1100,easing:'ease-in-out'}).finished;});rustle();await Promise.all(animations);if(token!==generation)return;pile=[...pile.slice(split),...pile.slice(0,split)];busy=false;drawStack();progress(1);$('status').textContent='Колода снята. Верхняя карта ждёт — нажми на неё или потяни вниз.';}
async function takeCard(){if(busy||selected.length>=limit())return;busy=true;if(!selected.length){allowReversed=$('reversed').checked;}controls();const token=generation;const i=selected.length,entry=pile.pop();if(entry.orientationAssigned!==true){entry.reversed=allowReversed&&randomIndex(2)===1;entry.orientationAssigned=true;}selected.push(entry);if(spreadType==='free'&&!document.querySelector(`[data-slot="${i}"]`)){positions.push('Карта '+(i+1));appendSlot(i);}const source=$('deck-hit').getBoundingClientRect(),target=document.querySelector(`[data-slot="${i}"]`),dest=target.getBoundingClientRect();const flying=document.createElement('div');flying.className='flying-card';flying.innerHTML=back();flying.style.cssText=`left:${source.left}px;top:${source.top}px;width:${source.width}px;height:${source.height}px`;document.body.append(flying);drawStack();rustle();$('status').textContent=`Вытягиваем карту: ${positions[i].toLowerCase()}…`;if(!reducedMotion)await flying.animate([{transform:'translate(0,0) rotate(-7deg)'},{transform:`translate(${(dest.left-source.left)*.6}px,${(dest.top-source.top)*.35-55}px) rotate(8deg)`,offset:.45},{transform:`translate(${dest.left-source.left}px,${dest.top-source.top}px) rotate(0)`,width:`${dest.width}px`,height:`${dest.height}px`}],{duration:760,easing:'cubic-bezier(.22,.7,.2,1)'}).finished;flying.remove();if(token!==generation)return;target.innerHTML=`<div class="flip-card"><div class="flip-inner"><div class="flip-back">${back()}</div><div class="flip-front">${cardSVG(entry.card)}</div></div></div>`;if(entry.reversed)target.querySelector('svg').style.transform='rotate(180deg)';target.disabled=false;target.setAttribute('aria-label',`Открыть карту: ${positions[i]}`);target.closest('.slot').classList.remove('empty-slot');target.nextElementSibling.textContent='Нажми, чтобы открыть';busy=false;controls();$('table-scene').classList.add('camera-close');progress(selected.length===limit()?2:1);$('status').textContent=selected.length===limit()?'Карты на столе. Нажми на любую, чтобы прочитать её.':`Карта на столе. Можно открыть её или вытянуть следующую (${selected.length} из ${limit()}).`;}
$('shuffle').addEventListener('click',shuffle);$('cut').addEventListener('click',cutDeck);$('draw').addEventListener('click',takeCard);$('deck-hit').addEventListener('click',takeCard);
document.querySelectorAll('[data-method]').forEach(b=>b.addEventListener('click',()=>{if(busy||selected.length)return;method=b.dataset.method;document.querySelectorAll('[data-method]').forEach(n=>{n.classList.toggle('active',n===b);n.setAttribute('aria-pressed',String(n===b))});$('status').textContent=({overhand:'Пакетами: небольшие стопки переходят из руки в руку.',riffle:'Впереплёт: две половинки соединяются в одну колоду.',wash:'На столе: карты расходятся в стороны и собираются обратно.'})[method]}));
let drag=null,suppressClick=false;const hit=$('deck-hit');hit.addEventListener('pointerdown',e=>{if(busy||selected.length>=limit()||e.button>0)return;drag={x:e.clientX,y:e.clientY,id:e.pointerId};hit.setPointerCapture(e.pointerId)});hit.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;const top=$('deck-stack').lastElementChild;if(top)top.style.transform=`translate3d(${dx*.65}px,${dy*.65}px,${pile.length*.38+15}px) rotateZ(${dx*.08}deg)`;});hit.addEventListener('pointerup',e=>{if(!drag)return;const distance=Math.hypot(e.clientX-drag.x,e.clientY-drag.y);drag=null;if(distance>28){suppressClick=true;takeCard();setTimeout(()=>suppressClick=false,50)}else drawStack()});hit.addEventListener('click',e=>{if(suppressClick){e.stopImmediatePropagation();e.preventDefault()}},true);hit.addEventListener('pointercancel',()=>{drag=null;drawStack()});
$('spread').addEventListener('click',e=>{const b=e.target.closest('[data-slot]');if(!b||busy)return;const i=+b.dataset.slot;if(!selected[i])return;if(revealed.has(i)){openReading(i);return;}revealed.add(i);const {card,reversed}=selected[i];b.querySelector('.flip-inner').classList.add('turned');rustle(.5);b.setAttribute('aria-label',`${positions[i]}: ${card.name}${reversed?', перевёрнутая карта':''}`);b.nextElementSibling.textContent=card.name+(reversed?' · Перевёрнутая':'');showResults();openReading(i);controls();if(revealed.size===selected.length&&selected.length>0){progress(3)}else $('status').textContent=`Открыто карт: ${revealed.size} из ${selected.length}. ${selected.length<limit()?'Следующая ждёт сверху колоды.':'Открой оставшиеся карты.'}`;});
$('restart-table').addEventListener('click',()=>{if(!busy)reset()});
function interpretation(entry,index){return (spreadType==='free'?'':`Позиция «${positions[index]}». `)+(entry.reversed?entry.card.reading.historical.reversed:entry.card.reading.historical.upright);}
function showResults(){const opened=openedEntries();$('results').hidden=opened.length===0;$('asked').textContent='';$('interpretations').innerHTML=combinationHTML(opened)+selected.map((e,i)=>revealed.has(i)?`<article class="interpretation"><div><small>${escapeXML(positions[i])}</small><h3>${escapeXML(e.card.name)}</h3><small>${e.reversed?'Перевёрнутая':'Прямая'} · ${escapeXML(e.card.keyword)}</small></div><div><p class="interpretation-origin">Значение по Уэйту</p><p>${escapeXML(interpretation(e,i))}</p><p class="reading-source">Краткий перевод отдельных значений из исторического источника, не полный перевод.</p><button class="outline" data-read="${i}">Разобрать карту с разных сторон</button></div></article>`:'').join('');}
$('again').addEventListener('click',()=>{reset();$('reading').scrollIntoView({behavior:'smooth'})});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{for(const id of ['reading','gallery'])$(id).hidden=id!==b.dataset.view;document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));window.scrollTo({top:0,behavior:'smooth'})}));
const filters=[['all','Вся колода'],['major','Старшие арканы'],...suits.map(s=>[s.id,s.name])];$('filters').innerHTML=filters.map(([id,name],i)=>`<button data-filter="${id}" class="${i===0?'active':''}">${name}</button>`).join('');
function gallery(filter='all'){const list=deck.filter(c=>filter==='all'||c.family===filter);$('count').textContent=`Карт в разделе: ${list.length}`;$('cards').innerHTML=list.map(c=>`<article><button class="card-button" data-card="${c.id}" aria-label="Узнать о карте: ${escapeXML(c.name)}">${cardSVG(c)}</button><p>${escapeXML(c.name)}</p></article>`).join('');}
$('filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;document.querySelectorAll('[data-filter]').forEach(n=>n.classList.toggle('active',n===b));gallery(b.dataset.filter)});
$('cards').addEventListener('click',e=>{const b=e.target.closest('[data-card]');if(!b)return;const c=deck[+b.dataset.card];$('detail-body').innerHTML=cardSVG(c)+`<div><div class="eyebrow">${c.family==='major'?'СТАРШИЙ АРКАН':suits.find(s=>s.id===c.family).name.toUpperCase()}</div><h2>${escapeXML(c.name)}</h2><p>${escapeXML(c.meaning)}</p><p><strong>Попробуй:</strong> ${escapeXML(c.tip)}</p></div>`;if(!$('detail').open)$('detail').showModal()});$('close').addEventListener('click',()=>$('detail').close());$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close()}});initializeUX();reset();gallery();

function appendSlot(i){$('spread').insertAdjacentHTML('beforeend',`<div class="slot"><span>${escapeXML(positions[i])}</span><button class="card-button table-slot" data-slot="${i}" disabled><div class="slot-placeholder"><span>${i+1}</span></div></button><small>Карта ждёт в колоде</small></div>`);}
function sourceNote(){return `<p class="reading-source">Основа: <a href="https://sacred-texts.com/book/the-pictorial-key-to-the-tarot" target="_blank" rel="noopener noreferrer">А. Э. Уэйт, «Иллюстрированный ключ к Таро» (1911)</a>. Здесь — краткий пересказ мотивов, а не дословный перевод. Советы по сферам и сочетания — современная авторская интерпретация, не правила самого Уэйта.</p>`;}
function memoContent(c,reversed=false){const r=c.reading,x=CARD_ESSAYS[c.name],long=LONG_CARD_READINGS[c.name];const paragraphs=items=>items.map(t=>`<p>${escapeXML(t)}</p>`).join('');const journey=long?.journey||[x.deep];const love=long?.love||[r.love];const work=long?.work||[r.work];const reversedText=long?.reversed||[r.reversed];const symbolText=[r.symbol,...(long?.symbols||[])];const questions=long?.questions||[x.question,`Как в моих обстоятельствах проявляется тема «${r.theme}»?`,`Что я могу проверить на практике, прежде чем делать вывод?`];const wordCount=[r.upright,...journey,...love,...work,...reversedText,...symbolText,x.example,x.pitfall,...questions].join(' ').split(/\s+/).length;return cardSVG(c)+`<div class="rich-reading"><div class="eyebrow">${c.family==='major'?'СТАРШИЙ АРКАН':suits.find(s=>s.id===c.family).name.toUpperCase()}</div><h2>${escapeXML(c.name)}</h2><p class="reading-theme">${escapeXML(r.theme)}</p><p class="reading-length">Чтение в своём темпе · около ${Math.max(2,Math.ceil(wordCount/160))} мин.</p><nav class="reading-jumps" aria-label="Разделы трактовки"><button data-reading-section="waite">Уэйт</button><button data-reading-section="reflections">Размышления</button><button data-reading-section="practical">Совет</button></nav>${historicalContent(c,reversed)}<section class="additional-reflections" data-chapter="reflections"><h3 class="origin-heading">Дополнительные размышления</h3><p class="origin-note">Современный авторский комментарий сайта. Это не текст Уэйта и не историческое толкование.</p><section class="reading-focus"><h3>${reversed?'Карта выпала перевёрнутой':'Коротко о карте'}</h3><p>${escapeXML(reversed?r.reversed:r.upright)}</p></section><section data-chapter="story" class="reading-story"><h3>История и глубинный смысл</h3>${paragraphs(journey)}<p>Эта карта может описывать обстоятельства, способ действовать или внутренний отклик. Чтобы выбрать подходящий ракурс, вспомни свой вопрос и конкретные события: один и тот же символ не обязан одинаково проявляться у разных людей.</p></section><details open><summary>Образ и символы</summary>${paragraphs(symbolText)}<p class="reading-source">Описание относится к традиционной карте Уэйта—Смит; иллюстрация с миньоном — свободная стилизация.</p></details><details ${reversed?'open':''}><summary>${reversed?'Перевёрнутое положение подробнее':'Если карта перевёрнута'}</summary>${paragraphs(reversedText)}<p>Сравни эту формулировку с прямым значением и обстоятельствами вопроса. Переворот не обязан быть противоположностью прямой карты или указанием на плохой исход.</p>${reversed?`<h3>Для сравнения: прямая карта</h3><p>${escapeXML(r.upright)}</p>`:''}</details><details data-chapter="relationships"><summary>В отношениях и близости</summary>${paragraphs(love)}${!long?'<p>Вспомни конкретную ситуацию между вами. Что было сказано, что сделано и что осталось только ожиданием? Такое разделение помогает обсудить потребность, не выдавая догадку о другом человеке за факт.</p>':''}</details><details><summary>В работе и повседневных делах</summary>${paragraphs(work)}${!long?'<p>Отнеси совет к одной задаче, а не ко всей жизни сразу. Назови доступный ресурс, реальное ограничение и действие, результат которого сможешь заметить. Тогда трактовка станет поводом проверить подход, а не заменой решения.</p>':''}</details><details open><summary>Как это может выглядеть в жизни</summary><p>${escapeXML(x.example)}</p><p>Это пример, а не описание твоей ситуации. Если он не откликается, обратись к основной теме карты и попробуй найти собственный, более точный пример.</p></details><section class="reading-practice" data-chapter="practical"><h3>Что можно попробовать</h3><p>${escapeXML(long?.practice||c.tip)}</p><h3>С чем стоит быть осторожнее</h3><p>${escapeXML(x.pitfall)}</p><h3>Вопросы к себе</h3><ol>${questions.map(q=>`<li>${escapeXML(q)}</li>`).join('')}</ol></section><details><summary>Как читать карту рядом с другими</summary><p>Сначала назови её тему: «${escapeXML(r.theme)}». Затем посмотри, продолжает ли соседняя карта этот мотив, предлагает другой способ действовать или показывает затруднение.</p><p>В свободном раскладе порядок не означает прошлое, настоящее и будущее. После открытия второй карты можно посмотреть общий разбор. Если связь не складывается, не нужно подгонять обстоятельства под красивую историю.</p></details></section>${sourceNote()}</div>`;}
function openReading(i){const e=selected[i];const opened=openedEntries();$('detail-body').innerHTML=memoContent(e.card,e.reversed)+`<div class="sheet-next"><p>${escapeXML(positions[i])} · ${e.reversed?'Перевёрнутая':'Прямая'}</p>${opened.length>1?'<button class="outline" id="open-combination">Как эти карты связаны? </button>':''}<button class="outline ask-chatgpt" data-chatgpt>Спросить ChatGPT</button><button class="gold" id="continue-reading">Вернуться к колоде </button></div>`;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0;$('continue-reading').onclick=()=>$('detail').close();if($('open-combination'))$('open-combination').onclick=openCombination;}
function undo(){if(busy||!selected.length)return;const entry=selected.pop();pile.push(entry);revealed.delete(selected.length);document.querySelector(`[data-slot="${selected.length}"]`)?.closest('.slot').remove();if(spreadType!=='free'||selected.length===0){if(spreadType==='free')positions=['Карта 1'];appendSlot(selected.length);}else positions.pop();$('table-scene').classList.toggle('camera-close',selected.length>0);drawStack();showResults();if(!revealed.size)$('results').hidden=true;progress(selected.length?1:0);$('status').textContent='Последняя карта возвращена наверх колоды.';}
async function exportReading(){if(!revealed.size)return;const button=$('export');button.disabled=true;try{const entries=selected.map((e,i)=>({...e,index:i})).filter(e=>revealed.has(e.index));const width=1080,cols=Math.min(3,entries.length),cell=width/cols,rows=Math.ceil(entries.length/cols);const canvas=document.createElement('canvas');canvas.width=width;canvas.height=170+rows*(cell*1.63+95)+80;const ctx=canvas.getContext('2d');ctx.fillStyle='#0b0c16';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#dbc18b';ctx.textAlign='center';ctx.font='34px Georgia';ctx.fillText('БАНАНОВЫЙ ОРАКУЛ',540,65);ctx.font='20px sans-serif';ctx.fillText($('spread-type').selectedOptions[0].textContent+' · '+new Date().toLocaleDateString('ru-RU'),540,108);for(let j=0;j<entries.length;j++){const e=entries[j],x=(j%cols)*cell+25,y=150+Math.floor(j/cols)*(cell*1.63+95),w=cell-50,h=w*1.63;const image=new Image();const url=URL.createObjectURL(new Blob([cardSVG(e.card)],{type:'image/svg+xml;charset=utf-8'}));try{image.src=url;await image.decode();ctx.save();if(e.reversed){ctx.translate(x+w,y+h);ctx.rotate(Math.PI);ctx.drawImage(image,0,0,w,h)}else ctx.drawImage(image,x,y,w,h);ctx.restore();ctx.fillStyle='#eee2c8';ctx.font='18px sans-serif';ctx.fillText(positions[e.index],x+w/2,y+h+30);ctx.font='15px sans-serif';ctx.fillText(e.card.name+(e.reversed?' · Перевёрнутая':''),x+w/2,y+h+57)}finally{URL.revokeObjectURL(url)}}const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));const file=new File([blob],'tarot.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})&&navigator.userActivation?.isActive)await navigator.share({files:[file],title:'Мой расклад'});else{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tarot.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}$('status').textContent='Изображение расклада готово.';}catch(e){console.warn('Image export:', e.name, e.message);$('status').textContent=e.name==='AbortError'?'Отправка отменена.':'Не удалось сохранить изображение. Попробуй ещё раз.';}finally{controls()}}
function initializeUX(){
$('spread-type').addEventListener('change',()=>{spreadType=$('spread-type').value;reset()});$('major-only').addEventListener('change',reset);$('undo').addEventListener('click',undo);$('export').addEventListener('click',exportReading);$('interpretations').addEventListener('click',e=>{const b=e.target.closest('[data-read]');if(b)openReading(+b.dataset.read)});
// Capture the memo click before the legacy gallery handler.
$('cards').addEventListener('click',e=>{const b=e.target.closest('[data-card]');if(!b)return;e.stopImmediatePropagation();$('detail-body').innerHTML=memoContent(deck[+b.dataset.card]);if(!$('detail').open)$('detail').showModal()},true);
$('memo-search').addEventListener('input',()=>{const q=$('memo-search').value.toLocaleLowerCase('ru');document.querySelectorAll('#cards article').forEach(a=>a.hidden=!a.textContent.toLocaleLowerCase('ru').includes(q))});
}

function openedEntries(){return selected.map((e,i)=>({...e,index:i})).filter(e=>revealed.has(e.index));}
const FAMILY_LENS={major:'важные жизненные ориентиры',wands:'инициатива и действие',cups:'чувства и близость',swords:'мысли, решения и трудные разговоры',pentacles:'ресурсы, труд и устойчивость'};
const FAMILY_BRIDGE={
'cups|pentacles':'Чувство получает практическую проверку: поддерживается ли близость временем, заботой и надёжными действиями?',
'cups|swords':'Слова и переживания могут расходиться. Полезно назвать чувство, затем отдельно проверить вывод, который из него сделан.',
'cups|wands':'Эмоциональный отклик встречается с желанием действовать. Сверь взаимность и темп, чтобы порыв не опередил согласие.',
'pentacles|swords':'Решение нужно сопоставить с ресурсами. Какая мысль помогает делу, а какая лишь добавляет напряжение?',
'pentacles|wands':'Импульсу требуется материальная опора. Проверь время, силы и условия, которые превратят намерение в устойчивую практику.',
'swords|wands':'Действие и суждение усиливают друг друга при ясной цели; без неё скорость рискует усилить конфликт.'};
const SPECIAL_PAIRS=[
[[16,17],'После пересмотра ненадёжной опоры появляется тема восстановления. Башня и Звезда предлагают не спешить строить прежнее заново: сначала выясни, что действительно поддерживает.'],
[[18,19],'Луна и Солнце противопоставляют неясность и открытость. Вместо угадывания скрытого найди факт или разговор, который делает ситуацию видимой.'],
[[13,0],'Завершение и новое начало связаны, но промежуток между ними может требовать времени. Необязательно знать весь маршрут, чтобы обозначить, что ты оставляешь позади.'],
[[15,11],'Сила рядом с Дьяволом ставит вопрос об управлении импульсом: где спокойная выдержка возвращает выбор, а где давление лишь усиливает привязанность?'],
[[6,37],'Влюблённые и Двойка Кубков соединяют личный выбор с взаимностью. Притяжение получает более надёжную основу через согласие и ясный обмен ожиданиями.'],
[[1,22],'Маг и Туз Жезлов соединяют возможность начать с умением воплотить замысел. Выбери один доступный инструмент и испытай идею в малом.'],
[[9,39],'Отшельник и Четвёрка Кубков ставят рядом полезное уединение и отстранённость от предложенного. Проверь, даёт ли пауза ясность или только закрепляет изоляцию.'],
[[31,45],'Десятка Жезлов и Десятка Кубков связывают нагрузку с образом общего благополучия. Не держится ли гармония на незаметной работе одного человека?']
];
function pairReading(a,b){const ar=a.card.reading,br=b.card.reading;const titles=`«${a.card.name}» + «${b.card.name}»`;const special=SPECIAL_PAIRS.find(([ids])=>ids.includes(a.card.id)&&ids.includes(b.card.id));let bridge;if(special)bridge=special[1];else if(a.card.family===b.card.family)bridge=`Обе карты рассматривают одну область — ${FAMILY_LENS[a.card.family]}. Это усиливает её значимость, но различие между темами «${ar.theme}» и «${br.theme}» не стоит стирать.`;else if(a.card.family==='major'||b.card.family==='major')bridge=`Старший аркан задаёт более широкий смысл, а другая карта предлагает рассмотреть его конкретное проявление. Как тема «${ar.theme}» связана с темой «${br.theme}» в твоём вопросе?`;else bridge=FAMILY_BRIDGE[[a.card.family,b.card.family].sort().join('|')];
if(a.reversed||b.reversed)bridge+=` Здесь ${a.reversed&&b.reversed?'обе карты перевёрнуты':'одна карта перевёрнута'}: не читай связь как простой переход к благоприятному результату. Для «${(a.reversed?a:b).card.name}» важно отдельное значение: ${(a.reversed?a:b).card.reading.reversed}`;
return {title:titles,text:bridge};}
function combinationHTML(entries){if(entries.length<2)return '<div class="combination-hint"><p>Открой ещё одну карту — появится чтение сочетания. Учитываются только открытые карты.</p></div>';const families={};for(const e of entries)families[e.card.family]=(families[e.card.family]||0)+1;const dominant=Object.entries(families).sort((a,b)=>b[1]-a[1]);const tied=dominant.length>1&&dominant[0][1]===dominant[1][1];const reversals=entries.filter(e=>e.reversed).length;let focus=tied?'Несколько областей представлены поровну: важно не сводить историю только к одной теме.':`Чаще встречается область «${FAMILY_LENS[dominant[0][0]]}»: ${dominant[0][1]} из ${entries.length} открытых карт.`;const pairs=entries.slice(1).map((e,i)=>pairReading(entries[i],e));return `<section class="combination"><div class="eyebrow">ДОПОЛНИТЕЛЬНЫЕ РАЗМЫШЛЕНИЯ · СОЧЕТАНИЯ</div><h3>Общая нить расклада</h3><p>${escapeXML(focus)}</p><p>${escapeXML(`Открыто карт: ${entries.length}. Из них перевёрнутых: ${reversals}. Количество переворотов само по себе не определяет хороший или плохой исход.`)}</p><p>${spreadType==='free'?'В свободном раскладе порядок — это последовательность твоего исследования, а не прошлое, настоящее и будущее.':'Позиции задают роли карт: одна может описывать обстоятельства, другая — препятствие или совет. Противоречие между ролями не обязательно означает ошибку.'}</p>${pairs.map((pair,i)=>`<details ${i===0?'open':''}><summary>${escapeXML(pair.title)}</summary><p>${spreadType==='free'?'':escapeXML(positions[entries[i].index]+' → '+positions[entries[i+1].index])+': '}${escapeXML(pair.text)}</p></details>`).join('')}<details><summary>Как собрать это в одну историю</summary><p>${entries.map(e=>escapeXML(positions[e.index]+' — '+e.card.reading.theme+(e.reversed?' (перевёрнутая)':''))).join(' → ')}.</p><p>Выбери связь, которая соответствует твоим обстоятельствам. Затем спроси: какой один шаг учитывает и возможность, и затруднение, показанные картами? Если образы не складываются, их не нужно соединять насильно.</p></details><p class="reading-source">Это авторский разбор по темам, мастям, положениям и соседству открытых карт. Он не является цитатой Уэйта или точным предсказанием. С новой картой разбор обновляется; скрытые карты в него не входят.</p></section>`;}
function openCombination(){$('detail-body').innerHTML=`<div class="combination-sheet">${combinationHTML(openedEntries())}${sourceNote()}<button class="outline ask-chatgpt" data-chatgpt>Спросить ChatGPT</button><button class="gold" id="back-to-deck">Вернуться к колоде </button></div>`;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0;$('back-to-deck').onclick=()=>$('detail').close();}

function buildChatGPTPrompt(){const entries=openedEntries();if(!entries.length)return '';const layout=$('spread-type').selectedOptions[0].textContent;return [
'Помоги подробно осмыслить мой расклад Таро на русском языке. Опирайся на символику Райдера—Уэйта—Смит и книгу А. Э. Уэйта «Иллюстрированный ключ к Таро» (1911). Не выдавай современные дополнения за цитаты Уэйта и честно отмечай различия традиций или неуверенность.',
'Тип расклада: '+layout+'. Используется '+($('major-only').checked?'только 22 старших аркана':'полная колода из 78 карт')+'.',
spreadType==='free'?'Это свободный расклад. Порядок карт не означает прошлое, настоящее и будущее. Не назначай картам роли, которых я не задавал.':'Позиции карт перечислены ниже; учитывай значение каждой позиции.',
'Я мысленно задал вопрос, но не записывал его. Если контекста недостаточно, предложи разные возможные прочтения и задай уточняющий вопрос. Не придумывай мою ситуацию.',
'Открытые карты в порядке вытягивания (закрытые карты не включены):',
...entries.map((e,i)=>{const r=e.card.reading;return `${i+1}. ${e.card.name}. Позиция: ${positions[e.index]}. Положение: ${e.reversed?'перевёрнутое':'прямое'}. Значение по Уэйту (краткий перевод выбранных значений, не полный перевод): ${e.reversed?r.historical.reversed:r.historical.upright} Источник: ${r.historical.source} Дополнительные размышления сайта (современный авторский текст, не цитата Уэйта): ${e.reversed?r.reversed:r.upright}`;}),
'Хочу получить содержательный разбор, а не несколько общих фраз:',
'1. Сначала дай раздел «Значение по Уэйту». Не включай туда современные психологические советы и не выдавай краткую справку сайта за полный перевод книги. Для каждой карты объясни её образ, символы и значение именно в выпавшем положении. Перевёрнутую карту не считай автоматически плохой или противоположной прямой.',
'2. В отдельном разделе «Дополнительные размышления» предложи ракурсы: отношения, работа и повседневные дела, внутреннее состояние. Обозначь их как возможные интерпретации, а не факты обо мне.',
entries.length>1?'3. Свяжи карты в целую историю: общие мотивы, контрасты, масти, повторения и переходы между соседними картами. Учитывай позиции и перевороты. Объясни, на чём основана каждая связь; не приписывай Уэйту несуществующие правила сочетаний.':'3. Это одна карта: не придумывай сочетания или отсутствующие карты.',
'4. Дай два альтернативных прочтения, если символы допускают разные выводы. Заверши несколькими вопросами для размышления и конкретными мягкими шагами.',
'Не обещай достоверного будущего, не делай медицинских диагнозов и не утверждай, что знаешь чужие мысли. Не используй эмодзи. Пиши спокойно, подробно и понятно.'
].join('\n\n');}
async function copyChatGPTPrompt(button){const prompt=buildChatGPTPrompt();if(!prompt)return;button.disabled=true;let copied=false;try{await navigator.clipboard.writeText(prompt);copied=true;}catch{}finally{button.disabled=false;}
$('detail-body').innerHTML=`<section class="clipboard-confirm"><div class="eyebrow">CHATGPT</div><h2>${copied?'Промпт скопирован':'Скопируй промпт вручную'}</h2><p role="status">${copied?'Промпт для вставки в ChatGPT скопирован в буфер обмена. Открой ChatGPT и вставь его в сообщение.':'Браузер не разрешил доступ к буферу обмена. Выдели и скопируй текст ниже.'}</p><p>Включены только открытые карты, их положения и выбранный тип расклада. Ничего не отправлено автоматически.</p>${copied?'<details><summary>Посмотреть промпт</summary>':''}<label for="chatgpt-prompt">Текст для ChatGPT</label><textarea id="chatgpt-prompt" readonly></textarea>${copied?'</details>':''}<a class="gold chatgpt-link" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Открыть ChatGPT</a><button class="outline" id="close-clipboard">Вернуться к раскладу</button></section>`;
$('chatgpt-prompt').value=prompt;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0;$('close-clipboard').onclick=()=>$('detail').close();if(!copied){$('chatgpt-prompt').focus();$('chatgpt-prompt').select();}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-chatgpt]');if(b)copyChatGPTPrompt(b)});

document.addEventListener('click',e=>{const button=e.target.closest('[data-reading-section]');if(!button)return;const chapter=$('detail-body').querySelector(`[data-chapter="${button.dataset.readingSection}"]`);if(!chapter)return;if(chapter.tagName==='DETAILS')chapter.open=true;chapter.scrollIntoView({behavior:reducedMotion?'instant':'smooth',block:'start'});});

function historicalContent(c,reversed=false){const h=c.reading.historical;return `<section class="historical-reading" data-chapter="waite"><h3 class="origin-heading">Значение по Уэйту</h3><p class="origin-note">Краткий перевод отдельных значений из «Иллюстрированного ключа к Таро» (1911). Не полный перевод и не дословная цитата.</p><div class="historical-current"><h4>${reversed?'Перевёрнутое положение · выпало сейчас':'Прямое положение'}</h4><p>${escapeXML(reversed?h.reversed:h.upright)}</p></div><details><summary>${reversed?'Для сравнения: прямое положение':'Перевёрнутое положение'}</summary><p>${escapeXML(reversed?h.upright:h.reversed)}</p></details><a class="historical-source" href="${escapeXML(h.source)}" target="_blank" rel="noopener noreferrer">Прочитать первоисточник</a><p class="reading-source">Исторический перечень содержит неоднозначные и резкие выражения. Это термины автора своей эпохи, а не сведения о твоей жизни, диагноз или обещание события.</p></section>`;}
